import { Printer } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

import { BARCODE_TEXT_STRINGS as S } from './barcode-text.strings'
import { useDeviceLabelPrint } from './useDeviceLabelPrint'
import { LabelPdfPreviewDialog } from './LabelPdfPreviewDialog'

interface BarcodeTextProps {
  children: React.ReactNode
  model?: string
  serial?: string
  className?: string
  /**
   * The device this barcode belongs to.
   *
   * When present the printer button fetches the REAL label — a 50x25mm PDF
   * carrying a scannable Code128, generated by the same service that prints an
   * assignment's sheet, so one label and a hundred come out identical.
   *
   * Without it the button falls back to the legacy HTML label below, which
   * renders the serial as TEXT and cannot be scanned. That fallback exists only
   * for call sites that have a barcode string and no device id; it is not a
   * label anyone should be sticking on a machine.
   */
  stockItemId?: string
  /** Hide the printer button entirely (show just the barcode text). Used where
   *  the barcode is only a reference, not something to print (e.g. the spares
   *  listing's device column). */
  hidePrint?: boolean
}

// Print the label from a hidden, same-page iframe instead of a popup window.
// The old `window.open(..., 'width=400,height=300')` opened a popup whose
// auto-`print()` dialog was modal to the whole browser window — it froze the
// device-listing tab until dismissed and left a stray tab behind. An iframe
// keeps everything in the current tab: the print dialog is tab-scoped, and the
// frame is torn down as soon as printing finishes (or is cancelled).
function printBarcodeLabel(barcode: string, model?: string, serial?: string) {
  const esc = (s: string) =>
    s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c] ?? c)

  const iframe = document.createElement('iframe')
  iframe.setAttribute('aria-hidden', 'true')
  iframe.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;'
  document.body.appendChild(iframe)

  const doc = iframe.contentWindow?.document
  if (!doc) {
    iframe.remove()
    toast.error(S.printFailed)
    return
  }

  let done = false
  const cleanup = () => {
    if (done) return
    done = true
    iframe.remove()
  }

  doc.open()
  doc.write(`
    <html>
      <head><title>Print Barcode</title>
        <style>@page { size: auto; margin: 0; } body { margin: 0; }</style>
      </head>
      <body style="font-family: monospace; margin: 0; min-height: 100vh; box-sizing: border-box; padding: 16px; display: flex; align-items: center; justify-content: center;">
        <div style="border: 2px solid #000; padding: 20px; text-align: center;">
          <div style="font-size: 24px; font-weight: bold; letter-spacing: 4px;">${esc(barcode)}</div>
          ${model ? `<div style="font-size: 12px; margin-top: 8px; color: #555;">${esc(model)}</div>` : ''}
          ${serial ? `<div style="font-size: 11px; margin-top: 4px; color: #777;">S/N: ${esc(serial)}</div>` : ''}
        </div>
      </body>
    </html>
  `)
  doc.close()

  const frameWin = iframe.contentWindow
  if (!frameWin) {
    cleanup()
    toast.error(S.printFailed)
    return
  }
  // Remove the frame once the dialog closes (printed or cancelled). A timeout
  // backstops browsers that don't fire `afterprint`.
  frameWin.addEventListener('afterprint', cleanup)
  window.setTimeout(cleanup, 60_000)
  frameWin.focus()
  frameWin.print()
}

export function BarcodeText({
  children,
  model,
  serial,
  className,
  stockItemId,
  hidePrint = false,
}: BarcodeTextProps) {
  const barcode = typeof children === 'string' ? children : String(children)
  const label = useDeviceLabelPrint()
  return (
    <span className={cn('inline-flex items-center gap-1.5', className)}>
      <span className="font-mono text-xs font-medium">{children}</span>
      {!hidePrint && (
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation()
            // A real device → the scannable PDF label, shown in an embedded
            // viewer to print/save from (Chrome blocks a scripted PDF print).
            // No device id → the legacy text-only HTML label via iframe print.
            if (stockItemId) {
              void label.print(stockItemId)
              return
            }
            printBarcodeLabel(barcode, model, serial)
          }}
          className="inline-flex size-5 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          title={S.printBarcode.title}
          aria-label={S.printBarcode.ariaLabel}
        >
          <Printer className="size-3.5" />
        </button>
      )}
      {/* The device PDF label, embedded for printing; only this row's dialog
          opens because each BarcodeText owns its own print hook. Its content is
          portaled, but React events still bubble up the component tree, so a
          click inside it (Close / backdrop) would reach a table row's onClick
          and navigate to the detail page. Stop that here. `display:contents`
          keeps the wrapper out of the flex layout so it adds no spacing. */}
      <span className="contents" onClick={(e) => e.stopPropagation()}>
        <LabelPdfPreviewDialog url={label.previewUrl} onClose={label.dismissPreview} />
      </span>
    </span>
  )
}
